-- ############################################################################################
-- #  s288 A-CORE - F1 / P-A - `documents.source_pdf_sha256`: placeholder -> sha REAL         #
-- #  PASTE MANUAL DE ALBERTO en el editor SQL de Supabase (stop-line del spec s288 s7).      #
-- ############################################################################################
--
-- QUE HACE
--   Sustituye el placeholder `backfill:<sha256 del NOMBRE del fichero>` por la sha REAL de
--   los BYTES del PDF fuente en los documents pre-registrados del packet P-A. La sha real
--   es la `extraction_sha256` UNICA de los chunks del propio documento (premisa H1 del spec
--   s2, veredicto del census F0: **H1_CONFIRMADA 60/60**, gate no-circular por clave stem).
--   Consecuencia buscada (spec sF2.3): esos documentos pasan a cumplir el predicado de
--   autoridad `tier blob-verificado` (activo + sha real 64-hex + binding extraction==source)
--   que la lane `doc_scoped_hyq_coverage` exige por parent.
--
-- QUE **NO** TOCA
--   Ninguna otra columna de `documents` (status, language, lineage, revision, FKs: intactos).
--   Ninguna fila de `chunks_v2` / `chunks_v2_hyq` / `chunks_v2_enunciados`. Ningun documento
--   fuera de la lista literal de abajo. NO acuna lineages (spec fix r2-2: P-C va por tramos).
--
-- PROCEDENCIA (freeze del insumo)
--   census F0        : evals/s288_acore_census_v2_result_v1.json (tag v1)
--   census sha256-LF : 4cbbbfbd30567c10b789796dbb7dd522cac07464f361c59b1d729678b1174d44
--   census commit    : adc8aa6  (s288 F0: census v2 EJECUTADO)
--   spec normativo   : evals/s288_acore_design_brief_v1.md  sha256-LF 1c1a65088681f6a37d5dcc87c7cd6a921d6ca32ab25364fe569b208fe75edc39
--   generador        : scripts/s288_acore_stage_pA.py  (determinista; NO editar a mano: re-emitir)
--   generador sha256 : 8e5722f94d84c0234bc1081022fcbff656d7213037aa0dc49fda1599a2e469ad
--
-- VOLUMEN PRE-REGISTRADO (spec F0(g) / fix r2-3 - el gate F3 compara contra estas cifras)
--   elegibles P-A pre-registrados por el census .......... 585
--   EXCLUIDOS por fallar una precondicion HOY ............ 0
--   **FILAS DE ESTE PACKET (== UPDATE esperado)** ........ 585
--   documents totales (ancla anti-deriva) ............... 1169
--   documents con placeholder ANTES del paste ........... 744
--   documents con placeholder DESPUES del paste ......... 159   (744 - 585)
--
-- EXCLUSIONES: NINGUNA. Los elegibles del pre-registro cumplen HOY todas las
--   precondiciones (i)-(iv), re-verificadas contra la DB en vivo por el generador
--   antes de emitir, mas el dual-key contra el manifest de blobs del census.
--
-- REVERSIBILIDAD
--   BACKUP: `documents_backup_s288_pa` (copia integra de las 585 filas ANTES del UPDATE).
--   El bloque ABORTA si esa tabla ya existe (patron s287 v2: un `IF NOT EXISTS` habria
--   hecho NO-OP en silencio y el paste correria SIN backup). ROLLBACK exacto al final.
--
-- DRY-RUN: cambia el `COMMIT;` final por `ROLLBACK;` — todos los guards y post-checks
--   corren igual y no se persiste nada.
--
-- ANCLAS ANTI-DERIVA que el bloque re-verifica en vivo antes de escribir:
--   * las 585 filas existen, estan `active` y llevan EXACTAMENTE ese placeholder;
--   * la sha destino NO esta ocupada por otro documento de la MISMA marca (UNIQUE
--     `documents_mfr_hash_unique`, migrations/001_document_management.sql:68) ni colisiona
--     dentro del propio packet;
--   * cada documento tiene EXACTAMENTE 1 `extraction_sha256` distinta y es la sha destino;
--   * documentos AJENOS al packet que comparten uno de sus placeholders: 0 (medido hoy);
--   * `documents` tiene 1169 filas y 744 placeholders;
--   * chunks de estos documentos SIN `extraction_sha256`: 0 (medido hoy, anclado).
-- ############################################################################################

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';

DO $s288_pa_map$
DECLARE
  c_expected   CONSTANT integer := 585;        -- filas del packet (== UPDATE esperado)
  c_docs_total CONSTANT integer := 1169;      -- census F0: particion suma 1169
  c_ph_pre     CONSTANT integer := 744;       -- placeholders ANTES
  c_ph_post    CONSTANT integer := 159;       -- placeholders DESPUES (744 - 585)
  c_sin_ext    CONSTANT integer := 0;        -- chunks de estos docs sin extraction_sha256
  c_ph_ajenos  CONSTANT integer := 0;        -- docs AJENOS que comparten un placeholder del packet
  n            integer;
  ids          text;
BEGIN
  -- ======================================================================== (a) VALORES
  -- Sin `DROP TABLE IF EXISTS` a proposito: si la temp ya existe en esta sesion es que un
  -- paste anterior COMMITEO (un fallo hace ROLLBACK y no deja rastro) -> abortar es lo
  -- correcto. Orden: document_id ascendente (determinismo de la emision).
  CREATE TEMP TABLE s288_pa_map (
    document_id     uuid PRIMARY KEY,
    sha_placeholder text NOT NULL CHECK (sha_placeholder LIKE 'backfill:%'),
    sha_destino     text NOT NULL CHECK (sha_destino ~ '^[0-9a-f]{64}$')
  );


  SELECT count(*) INTO n FROM s288_pa_map;
  IF n <> c_expected THEN
    RAISE EXCEPTION 'P-A: la tabla de valores tiene % filas, se esperaban % - ABORTA', n, c_expected;
  END IF;

  SELECT count(DISTINCT sha_destino) INTO n FROM s288_pa_map;
  IF n <> c_expected THEN
    RAISE EXCEPTION 'P-A: % sha destino distintas para % filas (el census pre-registro 0 grupos de sha compartida) - ABORTA', n, c_expected;
  END IF;

  -- ================================================================ (b) PRECONDICIONES
  -- (i) las filas existen, con EXACTAMENTE ese placeholder y status='active'
  SELECT count(*), coalesce(string_agg(m.document_id::text, ', ' ORDER BY m.document_id), '')
    INTO n, ids
    FROM s288_pa_map m
    LEFT JOIN documents d
      ON  d.id = m.document_id
      AND d.source_pdf_sha256 = m.sha_placeholder
      AND d.status = 'active'
   WHERE d.id IS NULL;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A (i): % documentos no estan {activo + ese placeholder exacto} - ABORTA. Ejemplos: %',
      n, left(ids, 400);
  END IF;

  -- (i-bis) NINGUN documento FUERA del packet lleva uno de estos valores de placeholder.
  --   El placeholder es sha256 del NOMBRE y el UNIQUE solo constrine (marca, sha): dos
  --   documentos de marcas distintas con el mismo nombre de fichero compartirian valor.
  --   Se comprueba ANTES de escribir para que el post-check global no aborte DESPUES
  --   del UPDATE por una fila ajena al packet.
  SELECT count(*) INTO n FROM documents d
   WHERE d.source_pdf_sha256 IN (SELECT sha_placeholder FROM s288_pa_map)
     AND d.id NOT IN (SELECT document_id FROM s288_pa_map);
  IF n <> c_ph_ajenos THEN
    RAISE EXCEPTION 'P-A (i-bis): % documentos AJENOS comparten un placeholder del packet, el generador midio % - ABORTA', n, c_ph_ajenos;
  END IF;

  -- (ii) guard del UNIQUE `documents_mfr_hash_unique` (manufacturer, source_pdf_sha256):
  --      la sha destino no puede estar ya ocupada por OTRO documento de la MISMA marca ...
  SELECT count(*), coalesce(string_agg(m.document_id::text || '->' || o.id::text, ', '
                            ORDER BY m.document_id), '')
    INTO n, ids
    FROM s288_pa_map m
    JOIN documents t ON t.id = m.document_id
    JOIN documents o ON o.manufacturer = t.manufacturer
                    AND o.source_pdf_sha256 = m.sha_destino
                    AND o.id <> m.document_id;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A (ii): % colisiones con el UNIQUE (manufacturer, sha destino) - ABORTA. Ejemplos: %',
      n, left(ids, 400);
  END IF;

  --      ... ni colisionar DENTRO del propio packet (dos docs de la misma marca al mismo sha)
  SELECT count(*) INTO n FROM (
    SELECT 1 FROM s288_pa_map m
      JOIN documents t ON t.id = m.document_id
     GROUP BY t.manufacturer, m.sha_destino HAVING count(*) > 1) x;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A (ii-bis): % colisiones INTRA-packet (manufacturer, sha destino) - ABORTA', n;
  END IF;

  -- (iii) cada documento tiene EXACTAMENTE 1 extraction_sha256 distinta y ES la sha destino
  SELECT count(*), coalesce(string_agg(g.document_id::text, ', ' ORDER BY g.document_id), '')
    INTO n, ids
    FROM (
      SELECT m.document_id,
             m.sha_destino,
             count(DISTINCT nullif(btrim(c.extraction_sha256), '')) AS n_ext,
             min(nullif(btrim(c.extraction_sha256), ''))            AS ext
        FROM s288_pa_map m
        LEFT JOIN chunks_v2 c ON c.document_id = m.document_id
       GROUP BY m.document_id, m.sha_destino) g
   WHERE g.n_ext <> 1 OR g.ext IS DISTINCT FROM g.sha_destino;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A (iii): % documentos sin extraction UNICA == sha destino - ABORTA. Ejemplos: %',
      n, left(ids, 400);
  END IF;

  --       ancla: chunks de estos documentos SIN extraction_sha256 (medido al generar)
  SELECT count(*) INTO n
    FROM s288_pa_map m
    JOIN chunks_v2 c ON c.document_id = m.document_id
   WHERE nullif(btrim(c.extraction_sha256), '') IS NULL;
  IF n <> c_sin_ext THEN
    RAISE EXCEPTION 'P-A (iii-bis): % chunks sin extraction_sha256, el generador midio % - ABORTA', n, c_sin_ext;
  END IF;

  -- (iv) anclas globales de corpus (census F0)
  SELECT count(*) INTO n FROM documents;
  IF n <> c_docs_total THEN
    RAISE EXCEPTION 'P-A (iv): documents tiene % filas, el census vio % - ABORTA', n, c_docs_total;
  END IF;

  SELECT count(*) INTO n FROM documents WHERE source_pdf_sha256 LIKE 'backfill:%';
  IF n <> c_ph_pre THEN
    RAISE EXCEPTION 'P-A (iv-bis): % documents con placeholder, se esperaban % - ABORTA', n, c_ph_pre;
  END IF;

  -- ========================================================================= (c) BACKUP
  IF to_regclass('public.documents_backup_s288_pa') IS NOT NULL THEN
    RAISE EXCEPTION 'P-A: la tabla de backup public.documents_backup_s288_pa YA EXISTE - ABORTA (no se reutiliza un nombre de backup: el paste correria sin red)';
  END IF;

  CREATE TABLE public.documents_backup_s288_pa AS
  SELECT d.* FROM documents d WHERE d.id IN (SELECT document_id FROM s288_pa_map);

  SELECT count(*) INTO n FROM public.documents_backup_s288_pa;
  IF n <> c_expected THEN
    RAISE EXCEPTION 'P-A: backup con % filas de % - ABORTA', n, c_expected;
  END IF;

  -- ========================================================================= (d) UPDATE
  UPDATE documents d
     SET source_pdf_sha256 = m.sha_destino
    FROM s288_pa_map m
   WHERE d.id = m.document_id
     AND d.source_pdf_sha256 = m.sha_placeholder
     AND d.status = 'active';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> c_expected THEN
    RAISE EXCEPTION 'P-A (d): UPDATE toco % filas, se esperaban % - ABORTA TODO', n, c_expected;
  END IF;
  RAISE NOTICE 'P-A: UPDATE aplicado a % documents', n;

  -- ==================================================================== (e) POST-CHECKS
  -- 1. los N documentos llevan AHORA la sha destino
  SELECT count(*) INTO n
    FROM s288_pa_map m JOIN documents d ON d.id = m.document_id
   WHERE d.source_pdf_sha256 = m.sha_destino;
  IF n <> c_expected THEN
    RAISE EXCEPTION 'P-A post-1: % de % documentos con la sha destino - ABORTA', n, c_expected;
  END IF;

  -- 2a. ninguno de los N documentos conserva su placeholder
  SELECT count(*) INTO n
    FROM s288_pa_map m JOIN documents d ON d.id = m.document_id
   WHERE d.source_pdf_sha256 = m.sha_placeholder;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A post-2a: % documentos del packet conservan su placeholder - ABORTA', n;
  END IF;

  -- 2b. en TODO el corpus solo pueden quedar con esos valores de placeholder las filas
  --     AJENAS que ya existian antes del paste (precondicion (i-bis))
  SELECT count(*) INTO n FROM documents d
   WHERE d.source_pdf_sha256 IN (SELECT sha_placeholder FROM s288_pa_map);
  IF n <> c_ph_ajenos THEN
    RAISE EXCEPTION 'P-A post-2b: quedan % filas con los placeholders del packet, se esperaban % - ABORTA', n, c_ph_ajenos;
  END IF;

  -- 3. BINDING: para los N, extraction_sha256 == source_pdf_sha256 (el predicado que la
  --    lane hyq exige en su tier blob-verificado; spec sF2.3)
  SELECT count(*) INTO n FROM (
    SELECT m.document_id FROM s288_pa_map m
      JOIN documents  d ON d.id = m.document_id
      LEFT JOIN chunks_v2 c ON c.document_id = m.document_id
     GROUP BY m.document_id, d.source_pdf_sha256
    HAVING count(DISTINCT nullif(btrim(c.extraction_sha256), '')) <> 1
        OR min(nullif(btrim(c.extraction_sha256), '')) IS DISTINCT FROM d.source_pdf_sha256) x;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P-A post-3: % documentos sin binding extraction==source_pdf_sha256 - ABORTA', n;
  END IF;

  -- 4. el corpus no cambio de tamano
  SELECT count(*) INTO n FROM documents;
  IF n <> c_docs_total THEN
    RAISE EXCEPTION 'P-A post-4: documents tiene % filas, se esperaban % - ABORTA', n, c_docs_total;
  END IF;

  -- 5. placeholders restantes en TODO el corpus == pre - N
  SELECT count(*) INTO n FROM documents WHERE source_pdf_sha256 LIKE 'backfill:%';
  IF n <> c_ph_post THEN
    RAISE EXCEPTION 'P-A post-5: quedan % placeholders, se esperaban % - ABORTA', n, c_ph_post;
  END IF;

  RAISE NOTICE 'P-A OK: % documents con sha real | placeholders %  -> % | backup en public.%',
    c_expected, c_ph_pre, c_ph_post, 'documents_backup_s288_pa';
END
$s288_pa_map$;

-- Resumen visible, DENTRO de la misma transaccion (la temp table vive hasta el fin de la
-- SESION; en el dry-run el ROLLBACK posterior la borra junto con todo lo demas).
-- Debe devolver: aplicados = 585 · placeholders_restantes = 159 · backup_filas = 585 · documents_total = 1169.
SELECT
  (SELECT count(*) FROM s288_pa_map m JOIN documents d ON d.id = m.document_id
    WHERE d.source_pdf_sha256 = m.sha_destino)                              AS aplicados,
  (SELECT count(*) FROM documents WHERE source_pdf_sha256 LIKE 'backfill:%') AS placeholders_restantes,
  (SELECT count(*) FROM public.documents_backup_s288_pa)                              AS backup_filas,
  (SELECT count(*) FROM documents)                                          AS documents_total;

COMMIT;   -- <-- para DRY-RUN: cambia esta linea por  ROLLBACK;


